import datetime

items = params.get("items") or []

status_counts = {}
priority_counts = {}
assignee_counts = {}
overdue_items = []

today = (datetime.datetime.utcnow() + datetime.timedelta(hours=8)).date()

for it in items:
    status = it.get("status") or "unknown"
    status_counts[status] = status_counts.get(status, 0) + 1

    priority = it.get("priority") or "unknown"
    priority_counts[priority] = priority_counts.get(priority, 0) + 1

    assignee_ids = it.get("assigneeIds") or []
    if assignee_ids:
        for aid in assignee_ids:
            assignee_counts[aid] = assignee_counts.get(aid, 0) + 1
    else:
        assignee_counts["unassigned"] = assignee_counts.get("unassigned", 0) + 1

    due_date = it.get("dueDate")
    if due_date and status not in ("done", "cancelled"):
        try:
            due = datetime.date.fromisoformat(due_date)
        except (ValueError, TypeError):
            due = None
        if due is not None and due < today:
            overdue_items.append(it)

overdue_count = len(overdue_items)
